                    semicolon(kt)));
          } else if (handler.contains("Mutiny")) {
            buffer.add(
                statement(
                    indent(controllerIndent),
                    "return ",
                    call,
                    ".onItem().transform(io.jooby.trpc.TrpcResponse::of)",
                    semicolon(kt)));
          } else {
