public List<String> generateMcpHandlerMethod(boolean kt) {
    String reqType = "";
    String resType = "";
    String toMethod = "";

    if (isMcpTool()) {
      reqType = "CallToolRequest";
      resType = "CallToolResult";
      toMethod = "toCallToolResult";
    } else if (isMcpPrompt()) {
      reqType = "GetPromptRequest";
      resType = "GetPromptResult";
      toMethod = "toPromptResult";
    } else if (isMcpResource() || isMcpResourceTemplate()) {
      reqType = "ReadResourceRequest";
      resType = "ReadResourceResult";
      toMethod = "toResourceResult";
    } else {
      return List.of();
    }

    List<String> buffer = new ArrayList<>();
    String handlerName = getMethodName();

    if (kt) {
      buffer.add(
          statement(
              indent(4),
              "private fun ",
              handlerName,
              "(exchange: io.modelcontextprotocol.server.McpSyncServerExchange?, transportContext:"
                  + " io.modelcontextprotocol.common.McpTransportContext, operation:"
                  + " io.jooby.mcp.McpOperation): io.modelcontextprotocol.spec.McpSchema.",
              resType,
              " {"));

      buffer.add(
          statement(indent(6), "val ctx = transportContext.get(\"CTX\") as? io.jooby.Context"));
      buffer.add(
          statement(
              indent(6),
              "val req_ = operation.request(io.modelcontextprotocol.spec.McpSchema.",
              reqType,
              "::class.java)"));
    } else {
      buffer.add(
          statement(
              indent(4),
              "private io.modelcontextprotocol.spec.McpSchema.",
              resType,
              " ",
              handlerName,
              "(io.modelcontextprotocol.server.McpSyncServerExchange exchange,"
                  + " io.modelcontextprotocol.common.McpTransportContext transportContext,"
                  + " io.jooby.mcp.McpOperation operation) {"));

      buffer.add(
          statement(
              indent(6),
              "var ctx = (io.jooby.Context) transportContext.get(\"CTX\")",
              semicolon(kt)));
      buffer.add(
          statement(
              indent(6),
              "var req_ = operation.request(io.modelcontextprotocol.spec.McpSchema.",
              reqType,
              ".class)",
              semicolon(kt)));
    }

    if (isMcpTool() || isMcpPrompt()) {
      if (kt) {
        buffer.add(statement(indent(6), "val args = operation.arguments()"));
      } else {
        buffer.add(statement(indent(6), "var args = operation.arguments()", semicolon(kt)));
      }
    } else if (isMcpResource() || isMcpResourceTemplate()) {
      String uriTemplate = extractAnnotationValue("io.jooby.annotation.mcp.McpResource", "uri");
      boolean isTemplate = isMcpResourceTemplate();

      if (isTemplate) {
        if (kt) {
          buffer.add(statement(indent(6), "val uri = req_.uri()"));
          buffer.add(
              statement(
                  indent(6),
                  "val manager = io.modelcontextprotocol.util.DefaultMcpUriTemplateManager(",
                  string(uriTemplate),
                  ")"));
          buffer.add(statement(indent(6), "val args = mutableMapOf<String, Any>()"));
          buffer.add(statement(indent(6), "args.putAll(manager.extractVariableValues(uri))"));
        } else {
          buffer.add(statement(indent(6), "var uri = req_.uri()", semicolon(kt)));
          buffer.add(
              statement(
                  indent(6),
                  "var manager = new io.modelcontextprotocol.util.DefaultMcpUriTemplateManager(",
                  string(uriTemplate),
                  ")",
                  semicolon(kt)));
          buffer.add(
              statement(
                  indent(6), "var args = new java.util.HashMap<String, Object>()", semicolon(kt)));
          buffer.add(
              statement(
                  indent(6), "args.putAll(manager.extractVariableValues(uri))", semicolon(kt)));
        }
      } else {
        if (kt) {
          buffer.add(statement(indent(6), "val args = emptyMap<String, Any>()"));
        } else {
          buffer.add(
              statement(
                  indent(6),
                  "var args = java.util.Collections.<String, Object>emptyMap()",
                  semicolon(kt)));
        }
      }
    }

    buffer.add(
        statement(indent(6), kt ? "val " : "var ", "c = this.factory.apply(ctx)", semicolon(kt)));

    List<String> javaParamNames = new ArrayList<>();
    for (var param : getParameters(true)) {
      var javaName = param.getName();
      var mcpName = param.getMcpName();
      var type = param.getType().getRawType().toString();
      var isNullable = param.isNullable(kt);
      javaParamNames.add(javaName);

      if (type.equals("io.jooby.Context")
          || type.equals("io.modelcontextprotocol.server.McpSyncServerExchange")
          || type.equals("io.modelcontextprotocol.common.McpTransportContext")) {
        continue;
      } else if (type.equals("io.modelcontextprotocol.spec.McpSchema." + reqType)) {
        buffer.add(statement(indent(6), kt ? "val " : "var ", javaName, " = req_", semicolon(kt)));
        continue;
      } else if (type.equals("io.jooby.mcp.McpOperation")) {
        buffer.add(
            statement(indent(6), kt ? "val " : "var ", javaName, " = operation", semicolon(kt)));
        continue;
      }

      if (kt) {
        buffer.add(
            statement(indent(6), "val raw_", javaName, " = args.get(", string(mcpName), ")"));

        if (!isNullable) {
          buffer.add(
              statement(
                  indent(6),
                  "if (raw_",
                  javaName,
                  " == null) throw IllegalArgumentException(",
                  string("Missing req param: " + mcpName),
                  ")"));
        }

        boolean isNumber = isNumber(type);

        if (isNumber) {
          String ktType = "Int";
          if (type.contains("Double") || type.equals("double")) ktType = "Double";
          else if (type.contains("Long") || type.equals("long")) ktType = "Long";
          else if (type.contains("Float") || type.equals("float")) ktType = "Float";
          else if (type.contains("Short") || type.equals("short")) ktType = "Short";
          else if (type.contains("Byte") || type.equals("byte")) ktType = "Byte";

          if (isNullable) {
            buffer.add(
                statement(
                    indent(6),
                    "val ",
                    javaName,
                    " = (raw_",
                    javaName,
                    " as? Number)?.to",
                    ktType,
                    "()"));
          } else {
            buffer.add(
                statement(
                    indent(6),
                    "val ",
                    javaName,
                    " = (raw_",
                    javaName,
                    " as Number).to",
                    ktType,
                    "()"));
          }
        } else if (type.equals("java.lang.String") || type.equals("String")) {
          buffer.add(
              statement(
                  indent(6),
                  "val ",
                  javaName,
                  " = raw_",
                  javaName,
                  isNullable ? "?.toString()" : ".toString()"));
        } else if (type.equals("boolean") || type.equals("java.lang.Boolean")) {
          buffer.add(
              statement(
                  indent(6),
                  "val ",
                  javaName,
                  " = raw_",
                  javaName,
                  " as Boolean",
                  isNullable ? "?" : ""));
        } else {
          buffer.add(
              statement(
                  indent(6),
                  "val ",
                  javaName,
                  " = raw_",
                  javaName,
                  " as ",
                  type,
                  isNullable ? "?" : ""));
        }

      } else {
        buffer.add(
            statement(
                indent(6),
                "var raw_",
                javaName,
                " = args.get(",
                string(mcpName),
                ")",
                semicolon(kt)));

        if (!isNullable) {
          buffer.add(
              statement(
                  indent(6),
                  "if (raw_",
                  javaName,
                  " == null) throw new IllegalArgumentException(",
                  string("Missing req param: " + mcpName),
                  ")",
                  semicolon(kt)));
        }

        boolean isNumber = isNumber(type);

        if (isNumber) {
          String primitiveName =
              switch (type) {
                case "double", "java.lang.Double" -> "double";
                case "long", "java.lang.Long" -> "long";
                case "float", "java.lang.Float" -> "float";
                case "short", "java.lang.Short" -> "short";
                case "byte", "java.lang.Byte" -> "byte";
                default -> "int";
              };

          buffer.add(
              statement(
                  indent(6),
                  "var ",
                  javaName,
                  " = ",
                  isNullable ? "(raw_" + javaName + " == null) ? null : " : "",
                  "((Number) raw_",
                  javaName,
                  ").",
                  primitiveName,
                  "Value()",
                  semicolon(kt)));

        } else if (type.equals("java.lang.String") || type.equals("String")) {
          buffer.add(
              statement(
                  indent(6),
                  "var ",
                  javaName,
                  " = raw_",
                  javaName,
                  " != null ? raw_",
                  javaName,
                  ".toString() : null",
                  semicolon(kt)));
        } else if (type.equals("boolean") || type.equals("java.lang.Boolean")) {
          buffer.add(
              statement(indent(6), "var ", javaName, " = (Boolean) raw_", javaName, semicolon(kt)));
        } else {
          buffer.add(
              statement(
                  indent(6), "var ", javaName, " = (", type, ") raw_", javaName, semicolon(kt)));
        }
      }
    }

    var methodCall = "c." + getMethodName() + "(" + String.join(", ", javaParamNames) + ")";

    String toMethodPrefix = (isMcpResource() || isMcpResourceTemplate()) ? "req_.uri(), " : "";

    // Resolve output schema flag for Handler runtime behavior
    String toMethodSuffix = "";
    if (isMcpTool()) {
      var outMeta = parseOutputSchemaMeta();
      boolean isEligible = hasOutputSchema();

      if (outMeta.isOff() || (!isEligible && outMeta.type() == null)) {
        toMethodSuffix = ", false";
      } else if (outMeta.type() != null) {
        toMethodSuffix = ", true";
      } else {
        toMethodSuffix = ", this.generateOutputSchema";
      }
    }

    if (getReturnType().isVoid()) {
      buffer.add(statement(indent(6), methodCall, semicolon(kt)));
      if (kt) {
        buffer.add(
            statement(
                indent(6),
                "return io.jooby.mcp.McpResult(this.json).",
                toMethod,
                "(",
                toMethodPrefix,
                "null",
                toMethodSuffix,
                ")"));
      } else {
        buffer.add(
            statement(
                indent(6),
                "return new io.jooby.mcp.McpResult(this.json).",
                toMethod,
                "(",
                toMethodPrefix,
                "null",
                toMethodSuffix,
                ")",
                semicolon(kt)));
      }
    } else {
      if (kt) {
        buffer.add(statement(indent(6), "val result = ", methodCall));
        buffer.add(
            statement(
                indent(6),
                "return io.jooby.mcp.McpResult(this.json).",
                toMethod,
                "(",
                toMethodPrefix,
                "result",
                toMethodSuffix,
                ")"));
      } else {
        buffer.add(statement(indent(6), "var result = ", methodCall, semicolon(kt)));
        buffer.add(
            statement(
                indent(6),
                "return new io.jooby.mcp.McpResult(this.json).",
                toMethod,
                "(",
                toMethodPrefix,
                "result",
                toMethodSuffix,
                ")",
                semicolon(kt)));
      }
    }
    buffer.add(statement(indent(4), "}", System.lineSeparator()));

    return buffer;
  }

