@Override
  public void run(CliContext ctx) throws Exception {
    Path projectDir = ctx.getWorkspace().resolve(name);
    if (Files.exists(projectDir)) {
      throw new IOException("Project directory already exists: " + projectDir);
    }
    Files.createDirectory(projectDir);
    String packageName;
    String version;
    String server;
    boolean stork = !gradle && this.stork;
    if (interactive) {
      gradle = yesNo(ctx.readLine("Use Gradle (yes/no): "));

      kotlin = yesNo(ctx.readLine("Use Kotlin (yes/no): "));

      packageName = ctx.readLine("Enter a groupId/package: ");

      version = ctx.readLine("Enter a version (1.0.0): ");
      if (version.trim().isEmpty()) {
        version = "1.0.0";
      }

      mvc = yesNo(ctx.readLine("Use MVC (yes/no): "));

      openapi = yesNo(ctx.readLine("Configure OpenAPI (yes/no): "));

      server = server(ctx.readLine("Choose a server (jetty, netty or undertow): "));

      if (!gradle) {
        stork =
            distribution(ctx.readLine("Distribution (uber/fat jar or stork): ")).equals("stork");
      }

      docker = yesNo(ctx.readLine("Generates Dockerfile (yes/no): "));
    } else {
      String[] parts = name.split(":");
      switch (parts.length) {
        case 3:
          packageName = parts[0];
          name = parts[1];
          version = parts[2];
          break;
        case 2:
          packageName = parts[0];
          name = parts[1];
          version = "1.0.0";
          break;
        default:
          packageName = "app";
          version = "1.0.0";
      }
      server = server(this.server);
    }
    String buildfile = gradle ? (kotlin ? "build.gradle.kts" : "build.gradle") : "pom.xml";
    String language = kotlin ? "kotlin" : "java";
    String extension = language.equalsIgnoreCase("kotlin") ? "kt" : "java";

    String finalArtifactId;
    if (gradle) {
      finalArtifactId = Paths.get("build", "libs", name + "-" + version + "-all.jar").toString();
    } else {
      finalArtifactId = name + "-" + version + (stork ? ".zip" : ".jar");
    }

    String serverClassName = serverClassName(server);

    Map<String, Object> model = new HashMap<>();
    Map<String, String> dependencyMap = ctx.getDependencyMap();
    model.putAll(dependencyMap);

    model.put("package", packageName);
    model.put("groupId", packageName);
    model.put("artifactId", name);
    model.put("version", version);
    model.put("joobyVersion", ctx.getVersion());
    model.put("server", server);
    model.put("serverClassName", serverClassName);
    model.put("serverPackageName", server);
    model.put("kotlin", kotlin);
    model.put("dependencies", dependencies(server, kotlin));
    model.put("testDependencies", testDependencies(dependencyMap));
    model.put("stork", stork);
    model.put("gradle", gradle);
    model.put("maven", !gradle);
    model.put("docker", docker);
    model.put("mvc", mvc);
    model.put("openapi", openapi);
    model.put("kapt", mvc && kotlin);
    model.put("apt", mvc && !kotlin);
    model.put("finalArtifactId", finalArtifactId);

    ctx.writeTemplate(buildfile, model, projectDir.resolve(buildfile));
    if (gradle) {
      ctx.writeTemplate("gradle.properties", model, projectDir.resolve("gradle.properties"));
    }

    // Copy conf
    Path confDir = projectDir.resolve("conf");
    ctx.copyResource("/cli/conf/application.conf", confDir.resolve("application.conf"));
    ctx.copyResource("/cli/conf/logback.xml", confDir.resolve("logback.xml"));

    ctx.writeTemplate("README.md", model, projectDir.resolve("README.md"));

    if (gradle) {
      gradleWrapper(ctx, projectDir, model);
    }

    if (stork) {
      stork(ctx, projectDir);
    }

    if (docker) {
      docker(ctx, projectDir, model);
    }

    /** Source directories: */
    Path sourcePath = projectDir.resolve("src").resolve("main");
    Path javaPath = sourcePath.resolve(language);
    Path packagePath =
        Stream.of(packageName.split("\\.")).reduce(javaPath, Path::resolve, Path::resolve);

    ctx.writeTemplate("App." + extension, model, packagePath.resolve("App." + extension));
    if (mvc) {
      ctx.writeTemplate(
          "Controller." + extension, model, packagePath.resolve("Controller." + extension));
    }

    /** Test directories: */
    Path testPath = projectDir.resolve("src").resolve("test");
    Path testJavaPath = testPath.resolve(language);
    Path testPackagePath =
        Stream.of(packageName.split("\\.")).reduce(testJavaPath, Path::resolve, Path::resolve);

    ctx.writeTemplate(
        "UnitTest." + extension, model, testPackagePath.resolve("UnitTest." + extension));
    ctx.writeTemplate(
        "IntegrationTest." + extension,
        model,
        testPackagePath.resolve("IntegrationTest." + extension));

    ctx.println("Try it! Open a terminal and type: ");
    ctx.println("  cd " + projectDir.toAbsolutePath());
    ctx.println("  " + (gradle ? "./gradlew joobyRun" : "mvn jooby:run"));
  }

@Override
  public void install(Jooby app) {
    var services = app.getServices();
    var mcpJsonMapper = services.require(McpJsonMapper.class);
    var globalGenerateOutputSchema =
        app.getConfig().hasPath("mcp.generateOutputSchema")
            ? app.getConfig().getBoolean("mcp.generateOutputSchema")
            : Optional.ofNullable(this.generateOutputSchema).orElse(Boolean.FALSE);
    // invoker
    McpInvoker pipeline = new McpExecutor(app);
    // Otel tracing goes first:
    if (head != null) {
      invoker = invoker == null ? head : head.then(invoker);
    }
    // Default invoker:
    if (this.invoker != null) {
      pipeline = this.invoker.then(pipeline);
    }
    services.put(McpInvoker.class, pipeline);
    // Group services by server
    var mcpServiceMap = new HashMap<String, List<McpService>>();
    for (var mcpService : mcpServices) {
      var localGenerateOutputSchemaPath =
          MODULE_CONFIG_PREFIX + "." + mcpService.serverKey() + ".generateOutputSchema";
      var localGenerateOutputSchema =
          app.getConfig().hasPath(localGenerateOutputSchemaPath)
              ? app.getConfig().getBoolean(localGenerateOutputSchemaPath)
              : globalGenerateOutputSchema;
      mcpService.generateOutputSchema(localGenerateOutputSchema);
      mcpServiceMap.computeIfAbsent(mcpService.serverKey(), k -> new ArrayList<>()).add(mcpService);
    }
    // Boot everything
    for (var serverEntry : mcpServiceMap.entrySet()) {
      var mcpConfig = mcpServerConfig(app, serverEntry.getKey());
      // Internal usage only, required by mcp-inspector
      services.listOf(McpServerConfig.class).add(mcpConfig);

      var capabilitiesBuilder = new McpSchema.ServerCapabilities.Builder();
      serverEntry.getValue().forEach(it -> it.capabilities(capabilitiesBuilder));

      var capabilities = capabilitiesBuilder.build();
      boolean stateless;
      if (mcpConfig.getTransport() == STATELESS_STREAMABLE_HTTP) {
        var transport =
            new StatelessTransportProvider(app, mcpJsonMapper, mcpConfig, CTX_EXTRACTOR);
        var statelessServer =
            McpServer.sync(transport)
                .serverInfo(mcpConfig.getName(), mcpConfig.getVersion())
                .completions(statelessCompletions(app, serverEntry))
                .capabilities(capabilities)
                .instructions(mcpConfig.getInstructions())
                .build();
        // install services
        serverEntry
            .getValue()
            .forEach(throwingConsumer(service -> service.install(app, statelessServer)));
        // bind registry
        services.putIfAbsent(McpStatelessSyncServer.class, statelessServer);
        services.put(
            ServiceKey.key(McpStatelessSyncServer.class, serverEntry.getKey()), statelessServer);
        services.listOf(McpStatelessSyncServer.class).add(statelessServer);

        stateless = true;

        app.onStop(statelessServer::close);
      } else {
        // Stupid MCP types, but it's the only way to make it work.
        var syncServer =
            (switch (mcpConfig.getTransport()) {
                  case STREAMABLE_HTTP ->
                      McpServer.sync(
                          new StreamableTransportProvider(
                              app, mcpJsonMapper, mcpConfig, CTX_EXTRACTOR));
                  case SSE ->
                      McpServer.sync(
                          new SseTransportProvider(app, mcpConfig, mcpJsonMapper, CTX_EXTRACTOR));
                  case WEBSOCKET ->
                      McpServer.sync(
                          new WebSocketTransportProvider(
                              app, mcpConfig, mcpJsonMapper, CTX_EXTRACTOR));
                  default ->
                      throw new IllegalStateException(
                          "Unsupported transport: " + mcpConfig.getTransport());
                })
                .serverInfo(mcpConfig.getName(), mcpConfig.getVersion())
                .completions(completions(app, serverEntry))
                .capabilities(capabilities)
                .instructions(mcpConfig.getInstructions())
                .build();
        // install service
        serverEntry
            .getValue()
            .forEach(throwingConsumer(service -> service.install(app, syncServer)));
        // bind registry
        services.putIfAbsent(McpSyncServer.class, syncServer);
        services.put(ServiceKey.key(McpSyncServer.class, serverEntry.getKey()), syncServer);
        services.listOf(McpSyncServer.class).add(syncServer);
        stateless = false;
        app.onStop(syncServer::close);
      }
      // Startup message:
      app.onStarting(
          () -> {
            var features = new ArrayList<String>();
            if (capabilities.tools() != null) features.add("Tools");
            if (capabilities.prompts() != null) features.add("Prompts");
            if (capabilities.resources() != null) features.add("Resources");
            var featuresStr = features.isEmpty() ? "None" : String.join(" | ", features);

            log.info(
                "MCP Server [{}({})] v{} online:",
                mcpConfig.getName(),
                serverEntry.getKey(),
                mcpConfig.getVersion());
            log.info("  ├─ Transport    : {}", mcpConfig.getTransport().getValue());
            if (!stateless) {
              log.info(
                  "  ├─ Keep-Alive   : {}",
                  mcpConfig.getKeepAliveInterval() == null
                      ? "N/A"
                      : mcpConfig.getKeepAliveInterval() + " s");
              log.info(
                  "  ├─ Session Rule : {}",
                  mcpConfig.isDisallowDelete() ? "Disallow Deletion (Strict)" : "Allow Deletion");
            }
            log.info("  ╰─ Capabilities : {}", featuresStr);
          });
    }
  }

